  user_id uuid not null references users(user_id),
  leave_type text not null,                                -- values driven by system_options (mod:leave / leave.types), not a DB enum
  reason text,
  start_date date not null,
  end_date date not null,
  total_days numeric,                                        -- REVIEW REQUIRED: type inferred only
  status text not null default 'pending' check (status in ('pending', 'approved', 'rejected')),
  stage text not null default 'pending_supervisor' check (stage in (
    'pending_supervisor', 'pending_signoff', 'approved', 'rejected'
  )),
