-- these may be plain `text` in the live database, enforced only in the app.
create table if not exists appraisals (
  id uuid primary key default gen_random_uuid(),
  company_id text not null,
  employee_name text not null,
  job_title text,
  current_grade text not null,
  section_authorisations_held text,
  immediate_supervisor text not null,
  supervisor_email text,
  employee_email text,
  cycle text,                                    -- 'quarterly' | 'annual', derived from review_quarter
  grade_band text not null,
  review_quarter text not null check (review_quarter in ('Q1', 'Q2', 'Q3', 'Q4')),
  review_year int not null,
  reviewing_manager text,
  period_covered text,
  promotion_readiness text,
  strengths_observed text,
  improvement_areas text,
  agreed_actions text,
  employee_comments text,
  most_significant_achievement text,
  development_plan_next_year text,
  promotion_readiness_assessment text,
  compensation_review_input text,
  employee_ratings jsonb,
  supervisor_ratings jsonb,
  employee_weighted_score numeric,
  supervisor_weighted_score numeric,
  employee_submitted_at timestamptz,
  supervisor_submitted_at timestamptz,
  supervisor_reviewed_by uuid,
  supervisor_reviewed_by_name text,
  submitted_by text default 'employee' check (submitted_by in ('employee', 'supervisor', 'both')),
  status text default 'open',                    -- REVIEW REQUIRED: values observed: 'open','submitted','final_reviewed','locked','reopened' — not confirmed as a real CHECK constraint
  deadline_at timestamptz,
  reopened_deadline_at timestamptz,
  employee_user_id uuid references users(user_id),
  supervisor_id uuid references users(user_id),
  final_review_date date,
  final_review_notes text,
  final_reviewed_by uuid,
  final_reviewed_by_name text,
  final_reviewed_at timestamptz,
  final_quarter_score numeric,
  employee_penalty_points numeric default 0,
  appeal_exhausted boolean default false,
  locked_reason text,                            -- REVIEW REQUIRED: values observed: 'employee_incomplete','supervisor_incomplete','reopen_incomplete'
  archived boolean default false,
  archived_at timestamptz,
  archived_by uuid,
  archived_by_name text,
  created_at timestamptz not null default now()
  -- REVIEW REQUIRED: no explicit unique constraint on (company_id,
  -- review_quarter, review_year) was found — "one appraisal per employee
  -- per cycle" appears to be enforced only in application code via
  -- upsert-by-select, not the database.
);

