-- is actually bigint (discovered via failed inserts in production). Using
-- the corrected type here.
create table if not exists content (
  id bigint generated by default as identity primary key,   -- REVIEW REQUIRED: exact identity/sequence definition not confirmed, "bigint" itself is confirmed
  title text not null,
  category text not null,
  sub_category text,
  description text,
  cover_image_url text,
  video_url text,
  video_duration_minutes int,
